static char *decrypt(const char *s) {
    size_t slen = strlen(s);
    size_t *starts = malloc((slen + 2) * sizeof(size_t));
    size_t *lens = malloc((slen + 2) * sizeof(size_t));
    int ngroups = 0;
    size_t begin = 0;
    for (size_t p = 0; p <= slen; p++) {
        if (p == slen || s[p] == '#') {
            starts[ngroups] = begin;
            lens[ngroups] = p - begin;
            ngroups++;
            begin = p + 1;
        }
    }
    if (slen > 0) {
        while (ngroups > 0 && lens[ngroups - 1] == 0)
            ngroups--;
    }
    int *crypt = malloc((slen + 2) * sizeof(int));
    int count = 0;
    int ends_with_hash = (slen > 0 && s[slen - 1] == '#');
    for (int i = 0; i < ngroups; i++) {
        const char *group = s + starts[i];
        int glen = (int)lens[i];
        int j = 0;
        if (i == ngroups - 1 && !ends_with_hash)
            j = glen;
        if (glen > 2)
            j = glen - 2;
        for (int k = 0; k < j; k++)
            crypt[count++] = group[k] - '0';
        if (j < glen) {
            int v = 0;
            for (int k = j; k < glen; k++)
                v = v * 10 + (group[k] - '0');
            crypt[count++] = v;
        }
    }
    char *n = malloc(count + 1);
    for (int i = 0; i < count; i++)
        n[i] = (char)('a' + crypt[i] - 1);
    n[count] = '\0';
    free(starts);
    free(lens);
    free(crypt);
    return n;
}

