static void normalize(char *t) {
    char *w = t;
    int pending_space = 0;
    for (char *r = t; *r; r++) {
        if (isspace((unsigned char)*r)) {
            pending_space = (w != t);
        } else {
            if (pending_space) {
                *w++ = ' ';
                pending_space = 0;
            }
            *w++ = *r;
        }
    }
    *w = '\0';
}

int main(void) {
