bool isPrime (int number) {
    if (number < 2 || (number != 2 && number % 2 == 0)) {
        return false;
    }
    int divisor = 3;
    while (divisor * divisor <= number) {
        if (number % divisor == 0) {
            return false;
        }
        divisor += 2;
    }
    return true;
}

